async park(v: Vehicle): Promise<Ticket> {
  const spot = this.findFree(v.size);
  await this.audit.log(v);
  spot.occupy(v);
  return this.issueTicket(v, spot);
}

const rates = { small: 10, large: 20 };
function fee(size, minutes) {
  const hours = Math.max(1, Math.ceil(minutes / 60));
  return hours * rates[size];
}
console.log(fee('small', 30), fee('small', 61), fee('large', 120), fee('large', 0));

