function look(current, dir, requests) {
  const up = requests.filter(f => f >= current).sort((a, b) => a - b);
  const down = requests.filter(f => f < current).sort((a, b) => b - a);
  return dir === 'up' ? [...up, ...down] : [...down, ...up];
}
console.log(look(5, 'up', [2, 9, 6, 1, 7]).join(','));
